"""Build a standalone local human review page; no API writes or inferred labels."""
import argparse
import json
from pathlib import Path

PAGE = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CrowdLens independent source review</title><style>
body{font:16px/1.5 system-ui;margin:0;background:#f4f6f7;color:#17232b}main{max-width:1100px;margin:auto;padding:28px}h1{margin-bottom:6px}section,article{background:white;border:1px solid #cbd5dc;border-radius:10px;padding:20px;margin:18px 0}button,input,select,textarea{font:inherit;padding:8px;border:1px solid #7e919e;border-radius:5px}button{cursor:pointer;background:#eaf3f1;margin:5px}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #156c61}textarea{width:95%;min-height:70px}label{display:block;margin:12px 0 4px}pre{white-space:pre-wrap;overflow-wrap:anywhere}nav{display:flex;flex-wrap:wrap}p{overflow-wrap:anywhere}.note{background:#fff7df;border-left:4px solid #a67700;padding:12px}.status{font-weight:600;color:#185d52}.grid{display:flex;gap:15px;flex-wrap:wrap}details{margin:12px 0}.sources article{background:#f8fbfc}small{color:#475d69}
</style><main><h1>CrowdLens independent source review</h1>
<p>Four fictional packets. Review what the sources support, not whether the fictional events occurred. Candidate origin and automatic findings are withheld.</p>
<p class="note">No ratings are filled in. Read sources first and create your reference facts before inspecting the candidate. Missing ratings and time remain unmeasured. Download saves your own JSONL locally; nothing is sent to a server. Download before closing or reloading; unsaved forms live only in this tab.</p>
<section aria-label="Reviewer provenance"><div class="grid"><div><label for="reviewer">Your stable reviewer ID</label><input id="reviewer" placeholder="Enter your own ID"></div><div><label for="kind">Reviewer kind</label><select id="kind"><option value="">Choose when reviewing</option><option value="human">Human</option><option value="expert_human">Expert human</option></select></div></div><small>These declarations require collector verification. AI-generated ratings must not be submitted as human ratings.</small></section>
<nav aria-label="Review packets" id="nav"></nav><p role="status" class="status" id="timer"></p><button id="start">Start active review timer</button><button id="pause">Pause active review timer</button>
<section><h2 id="title"></h2><p id="task"></p><div class="sources" id="sources"></div><label for="reference">Material reference facts, based only on sources (JSON array)</label><textarea id="reference" placeholder='[{"fact_id":"F1","text":"Source S01 says …"}]'></textarea><small>Leave blank if you have not made a reference assessment. Include source aliases or locators in each fact.</small><button id="show">Show candidate after reading sources</button></section>
<section id="candidate" hidden><h2>Candidate and claim review</h2><p>Numbered citations map to the source aliases below. Rate each listed claim against its sources and inspect linked draft wording. For analysis claims, inspect the premise-source chain; direct citations are not required. Record additional unlinked assertions or paraphrase errors in notes; they are not automatically counted as labelled claims.</p><pre id="citationMap"></pre><h3>Draft section</h3><pre id="section"></pre><details><summary>Candidate summary and proposed summary replacements</summary><pre id="summary"></pre></details><div id="claims"></div><label for="conflicts">Relevant conflicts handled?</label><select id="conflicts"><option value="">Unassessed</option><option value="true">Yes</option><option value="false">No</option></select><label><input type="checkbox" id="omissionAssessed"> I assessed omissions against my reference facts</label><label for="omissions">Omitted reference fact IDs (comma separated; blank means none only if assessed)</label><input id="omissions"><label for="notes">Additional unsupported draft assertions, disagreements or other notes</label><textarea id="notes"></textarea></section>
<button id="download">Download review forms (JSONL)</button><p role="alert" id="error"></p><label for="exported">Prepared JSONL (copy if browser download is unavailable)</label><textarea id="exported" readonly></textarea><small>Partial forms can be saved. A packet counts fully reviewed only after a human supplies support, attribution and citation judgments for every claim. Imports preserve disagreements and do not imply adjudication or sign-off.</small>
</main><script>const DATA=__DATA__;
const $=id=>document.getElementById(id);let current=0,started=null,fieldCounter=0;const measured=DATA.forms.map(()=>null);const references=DATA.forms.map(()=>''),omissions=DATA.forms.map(()=>''),assessed=DATA.forms.map(()=>false);
function node(tag,text,parent){const e=document.createElement(tag);e.textContent=text;parent.appendChild(e);return e}
function pause(){if(started!==null){measured[current]=(measured[current]||0)+(performance.now()-started)/1000;started=null}timer()}
function timer(){$('timer').textContent=started!==null?'Active review timer running':measured[current]===null?'Active review time: unmeasured':'Measured active review: '+measured[current].toFixed(1)+' seconds'}
function selection(parent,label,values,value,change){const id='field-'+current+'-'+(fieldCounter++);const lab=node('label',label,parent);lab.htmlFor=id;const s=node('select','',parent);s.id=id;for(const [v,t] of values){const o=node('option',t,s);o.value=v}s.value=value??'';s.onchange=()=>change(s.value);return s}
function render(){const p=DATA.packets[current],form=DATA.forms[current];$('candidate').hidden=true;$('show').textContent='Show candidate after reading sources';$('title').textContent='Packet '+(current+1)+' of '+DATA.packets.length;$('task').textContent=p.task;$('sources').replaceChildren();for(const s of p.sources){const a=node('article','',$('sources'));node('h3',s.source_id+' · original source'+(s.filename?' · '+s.filename:''),a);node('p',s.excerpt,a);node('small','Locator: '+JSON.stringify(s.locator),a)}$('reference').value=references[current];$('section').textContent=p.candidate_section;$('citationMap').textContent=Object.entries(p.citation_number_sources||{}).map(([n,s])=>'['+n+'] → '+s).join('\n');$('summary').textContent='Original comparison summary (not source evidence):\n'+(p.original_comparison_summary??'Not supplied in this packet')+'\n\nCandidate summary supplied for review:\n'+p.candidate_summary+'\n\nResolved spans and raw replacement requests (application state is recorded separately):\n'+JSON.stringify({resolved_edits:p.candidate_summary_edits||[],raw_replacements:p.candidate_summary_replacements||[],section_target:p.candidate_section_summary??null},null,2);$('claims').replaceChildren();for(const [i,c] of p.claims.entries()){const f=form.claims[i],a=node('article','',$('claims'));node('h3',c.claim_id+' · '+c.kind,a);node('p',c.text,a);node('p','Sources: '+(c.citation_ids||[]).join(', ')+' · Premises: '+(c.premise_claim_ids||[]).join(', '),a);selection(a,'Support',[['','Unassessed'],['supported','Supported'],['unsupported','Unsupported'],['ambiguous','Ambiguous'],['conflicting','Conflicting']],f.support,v=>f.support=v||null);for(const [key,label] of [['attribution_correct','Attribution correct?'],['citation_support_correct','Citation support correct?']])selection(a,label,[['','Unassessed'],['true','Yes'],['false','No']],f[key]===null?'':String(f[key]),v=>f[key]=v===''?null:v==='true');const lab=node('label','Rationale with source aliases and locators',a),t=node('textarea','',a);t.id='rationale-'+i;lab.htmlFor=t.id;t.value=f.rationale||'';t.oninput=()=>f.rationale=t.value||null}$('conflicts').value=form.conflicts_handled===null?'':String(form.conflicts_handled);$('omissionAssessed').checked=assessed[current];$('omissions').value=omissions[current];$('notes').value=form.notes||'';timer()}
DATA.packets.forEach((p,i)=>{const b=node('button','Packet '+(i+1),$('nav'));b.onclick=()=>{pause();current=i;render()}});$('start').onclick=()=>{if(started===null)started=performance.now();timer()};$('pause').onclick=pause;$('reference').oninput=()=>references[current]=$('reference').value;$('show').onclick=()=>{$('candidate').hidden=!$('candidate').hidden;$('show').textContent=$('candidate').hidden?'Show candidate after reading sources':'Hide candidate'};$('conflicts').onchange=()=>DATA.forms[current].conflicts_handled=$('conflicts').value===''?null:$('conflicts').value==='true';$('omissionAssessed').onchange=()=>assessed[current]=$('omissionAssessed').checked;$('omissions').oninput=()=>omissions[current]=$('omissions').value;$('notes').oninput=()=>DATA.forms[current].notes=$('notes').value||null;
$('download').onclick=()=>{pause();try{const rows=DATA.forms.map((f,i)=>{const row=structuredClone(f);row.reviewer_id=$('reviewer').value.trim()||null;row.reviewer_kind=$('kind').value||null;row.reviewed_at=row.reviewer_id&&row.reviewer_kind?new Date().toISOString():null;row.review_seconds=measured[i];row.draft_reference_facts_text=references[i]||null;if(assessed[i]){if(!references[i].trim())throw Error('Packet '+(i+1)+': omission assessment requires reference facts');row.reference_facts=JSON.parse(references[i]);row.omitted_reference_fact_ids=omissions[i].split(',').map(x=>x.trim()).filter(Boolean)}else{row.reference_facts=null;row.omitted_reference_fact_ids=null}return row});const text=rows.map(r=>JSON.stringify(r)).join('\n')+'\n';$('exported').value=text;const blob=new Blob([text],{type:'application/x-ndjson'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='crowdlens-human-reviews.jsonl';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);$('error').textContent='Forms prepared for local download; JSONL is also shown below. Retain originals for collector verification and import.'}catch(e){$('error').textContent=e.message}};render();
</script></html>'''


def build(directory):
    forms=[json.loads(line) for line in (directory/'blank-review-forms.jsonl').read_text().splitlines()]
    packets=[json.loads((directory/(f['packet_id']+'.json')).read_text()) for f in forms]
    data=json.dumps({'packets':packets,'forms':forms},ensure_ascii=False,allow_nan=False).replace('<','\\u003c')
    (directory/'index.html').write_text(PAGE.replace('__DATA__',data))


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--packets',type=Path,required=True);a=p.parse_args();build(a.packets)
